/* =========================================
   糯叽叽仿 Lysn 气泡美化 (暴力显示贴图版)
========================================= */

/* --- 0. 强行解除系统所有的裁切限制，防止贴图被吞 --- */
.message-wrapper, 
.msg-bubble-container, 
.msg-row, 
.msg-them {
  overflow: visible !important;
}

/* =========================================
   1. 我方气泡 (User) 样式
========================================= */
.bubble-me-custom {
  background-color: #a483f6 !important;
  color: #ffffff !important;
  padding: 8px 12px !important;

  /* 统一无连续气泡圆角：左上18 右上6 右下18 左下18 */
  border-radius: 14px 14px 6px 14px !important;
  box-shadow: none !important;
  border: none !important;

  /*🩵 气泡往右移动 (数值越大越往右) */
  position: relative !important;
  right: -5px !important; 
}

/* 强制隐藏我方头像 */
.msg-avatar-me-container { display: none !important; }

/* =========================================
   2. 对方气泡 (AI) 样式
========================================= */
.bubble-them-custom {
  background-color: #ffffff !important;
  color: #000000 !important;
  padding: 8px 12px !important;

  /* 统一无连续气泡圆角：左上6 右上18 右下18 左下18 */
  border-radius: 6px 14px 14px 14px !important;
  box-shadow: none !important;
  border: none !important;

  /* 必须加 relative，否则外挂的贴图找不到定位基准 */
  position: relative !important;
  /* 强制给气泡顶部腾出 35px 的空间，防止贴图和文字挤在上一条消息里看不见 */
  margin-top: 35px !important; 
  overflow: visible !important;
}

/* =========================================
   🩵3. AI气泡左上角：贴图与 "ㅇㅅㅇ" (核弹级显示)
========================================= */

/* A. 贴图强制注入 */
.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;

  /* 暴力唤醒，抗拒一切隐藏属性 */
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  z-index: 99999 !important; /* 层级拉满，绝不被遮挡 */

  /* 你的图片链接 */
  background-image: url("https://i.postimg.cc/fT1FpW5s/%E6%97%A0%E6%A0%87%E9%A2%98341_20260410183135.png") !important;
  background-size: 100% 100% !important; /* 强制拉伸填满，杜绝因尺寸计算错误导致的隐形 */
  background-repeat: no-repeat !important;
  background-color: transparent !important;

  /* 🩵在此调整贴图的大小和位置 */
  width: 40px !important;    /* 贴图宽度 */
  height: 20px !important;   /* 贴图高度 */
  top: -25px !important;     /* 上下位置数值越负，越飘在气泡上方 */
  left: 0px !important;      /* 左右位置 */
}

/* B. 文字强制注入 */
.bubble-them-custom::after {
  content: "ㅇㅅㅇ" !important;
  position: absolute !important;

  /* 暴力唤醒 */
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  z-index: 99999 !important;
  white-space: nowrap !important;

  /* 🩵在此调整文字的外观🩵 */
  color: #000000 !important;
  font-size: 14px !important;
  font-weight: 800 !important; /* 调整粗细 */

  /* 🩵在此调整文字的位置🩵 */
  top: -24px !important;     /* 建议与贴图的 top 保持接近 */
  left: 45px !important;     /* 左右位置，设在贴图宽度之外，让它紧挨着贴图右边 */
}

/* =========================================
   4. 预留：AI头像位置与距离调整
========================================= */
.msg-avatar-them-container {
  position: relative !important;
  /* 🩵 调整头像自身的上下左右 🩵 */
  top: 15px !important;
  left: 0px !important;
  /* 🩵 调整头像和右侧气泡的间隔 🩵 */
  margin-right: 8px !important; 
}
/* =========================================
   AI 头像高级渐变描边 (回归并修复版)
========================================= */

/* 1. 确保头像容器允许描边溢出显示 */
.msg-avatar-them-container {
  position: relative !important;
  overflow: visible !important; /* 必须可见，否则外扩的描边会被切掉 */
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  /* 🩵自由调整 AI 头像本体的上下左右位置🩵 */
  top: 15px !important;
  left: 0px !important;

  /* 🩵自由调整头像与右侧气泡的间隔🩵 */
  margin-right: 8px !important; 
}

/* 2. 强制渲染渐变描边层 */
.msg-avatar-them-container::after {
  content: "" !important;
  position: absolute !important;

  /* 确保描边在头像图层下面，往外露出来 */
  z-index: -1 !important; 
  display: block !important;
  visibility: visible !important;
  border-radius: 50% !important; /* 保持圆形 */

  /* 1. 自由更改描边的渐变角度和颜色 */
  background: linear-gradient(135deg, #d64fe6, #724df4) !important;

  /* 2. 自由更改描边与头像的间隔/距离 
     数值越负（例如-10px），描边离头像越远，圈圈越大 */
  top: -2px !important;
  bottom: -2px !important;
  left: -2px !important;
  right: -2px !important;

  /* 3. 自由更改描边的粗细 */
  padding: 1px !important;

  /* 🩵4. 自由微调整个描边圈圈的上下左右偏移
     如果你觉得圈圈没对准头像，可以调整这四个值 🩵*/
  margin-top: 0px !important;
  margin-left: 0px !important;

  /* 核心镂空技术：只保留外圈线，中间不遮挡头像 */
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}

/* 3. 强制让头像图片保持圆形且居中，防止挡住描边 */
.msg-avatar-them-container img, 
.msg-avatar-them-container .avatar-image {
  border-radius: 50% !important;
  z-index: 1 !important;
}
